          <div v-if="dashboard?.definitions.length" class="strategy-list">
            <button v-for="item in dashboard.definitions" :key="item.strategy_code" class="strategy-card" :class="{ selected: selected?.strategy_code === item.strategy_code }" @click="select(item)">
              <div class="strategy-card-head"><div><strong>{{ item.strategy_name }}</strong><small>{{ item.strategy_code }}</small></div><n-tag size="small" :type="statusType(item.status)" :bordered="false">{{ statusLabel(item.status) }}</n-tag></div>
              <p>{{ item.description || '尚未填写策略研究说明。' }}</p>
              <div class="strategy-meta"><span>{{ entryModeLabel(item.entry_mode) }}</span><span>最多 {{ item.max_holding_trade_days }} 个交易日</span><span>{{ item.pool_name || '策略池待创建' }}</span></div>
              <div class="strategy-counts"><span>候选 {{ item.candidate_summary.total_count || 0 }}</span><span>未触发 {{ item.candidate_summary.not_triggered_count || 0 }}</span><span>模拟成交 {{ item.trade_summary.total_count || 0 }}</span></div>
            </button>
          </div>
          <n-empty v-else description="尚未创建策略草稿" />
        </section>

        <section class="surface editor-surface">
          <template v-if="selected">
            <div class="panel-heading"><div><span class="panel-kicker">策略配置</span><h2>{{ selected.strategy_name }}</h2></div><n-tag :type="statusType(selected.status)" :bordered="false">{{ statusLabel(selected.status) }}</n-tag></div>
            <div class="settings-grid"><label>策略名称<n-input v-model:value="editForm.strategy_name" /></label><label>研究状态<n-select v-model:value="editForm.status" :options="statusOptions" /></label><div class="readonly-setting"><small>确认时点</small><b>{{ entryModeLabel(selected.entry_mode) }}</b></div><div class="readonly-setting"><small>默认最长持有</small><b>{{ selected.max_holding_trade_days }} 个交易日</b></div></div>
            <label class="description-label">研究说明<n-input v-model:value="editForm.description" type="textarea" :autosize="{ minRows: 4, maxRows: 8 }" placeholder="记录适用行情、候选逻辑、排除条件与回测观察。实现模板、确认时点和风险参数通过版本管理。" /></label>
            <div class="pool-boundary"><b>专属动态股票池</b><span>{{ selected.pool_name || '-' }}（{{ selected.pool_code || '-' }}）</span><small>以后只显示仍等待确认的策略候选；成交后转由持仓池监控，过期或未触发的候选会自然退出。</small></div>
            <div class="version-panel"><div class="version-heading"><div><b>版本、回测与模拟运行</b><small>市场门槛、候选上限和风险计划只能通过新版本修改。纸面基线按实际候选上限运行；寻优基线保留更多候选，只作历史参数研究，不能解锁 paper。</small></div><div class="version-actions"><n-button size="small" secondary @click="openCreateVersion">新建参数版本</n-button><n-button size="small" secondary :loading="loadingVersions" @click="loadVersions">刷新版本</n-button></div></div><div class="backtest-inputs"><label>回测开始<n-input v-model:value="backtestStartDate" placeholder="YYYY-MM-DD" /></label><label>回测结束<n-input v-model:value="backtestEndDate" placeholder="YYYY-MM-DD" /></label><label>寻优基线候选/日<n-input-number v-model:value="researchCandidateLimit" :min="30" :max="1000" :step="50" /></label></div><div v-if="selectedVersions.length" class="version-list"><div v-for="version in selectedVersions" :key="version.version_no" class="version-row"><span><b>v{{ version.version_no }}</b><small>{{ version.implementation_code }}</small></span><n-tag size="small" :type="versionStatusType(version.status)" :bordered="false">{{ versionStatusLabel(version.status) }}</n-tag><span class="version-metric">{{ versionMetric(version) }}</span><n-button size="tiny" secondary :loading="runningVersion === version.version_no" @click="runBacktest(version.version_no)">运行纸面基线</n-button><n-button size="tiny" secondary :loading="runningVersion === version.version_no" @click="runResearchBaseline(version.version_no)">运行寻优基线</n-button><n-button size="tiny" secondary :loading="optimizingVersion === version.version_no" @click="runOptimization(version.version_no)">历史参数寻优</n-button><n-button v-if="version.status === 'backtest_ready'" size="tiny" type="primary" :loading="promotingVersion === version.version_no" @click="promoteVersion(version.version_no)">提升为 paper</n-button></div></div><n-empty v-else size="small" description="暂无版本；请刷新或从内置模板创建策略。" /></div>
            <div class="backtest-review"><div class="version-heading"><div><b>基线回测审阅</b><small>先看样本区间、交易数、胜率、均值和中位数；满足技术门槛不代表值得进入 paper。</small></div><n-button size="tiny" secondary :loading="loadingBacktests" @click="loadBacktests">刷新记录</n-button></div><div v-if="backtestRuns.length" class="backtest-run-list"><div v-for="run in backtestRuns" :key="run.run_code" class="backtest-run"><span><b>{{ run.start_date }} ～ {{ run.end_date }}</b><small>{{ backtestRunStatusLabel(run.status) }} · {{ run.execution_model }}</small></span><span><b>{{ backtestSummaryNumber(run, 'signal_trade_date_count') }} 日 / {{ backtestSummaryNumber(run, 'completed_trade_count') }} 笔</b><small>胜率 {{ backtestSummaryPercent(run, 'win_rate_pct') }}</small></span><span><b :class="backtestReturnClass(run)">{{ backtestSummaryPercent(run, 'average_net_return_pct') }}</b><small>中位 {{ backtestSummaryPercent(run, 'median_net_return_pct') }}</small></span><n-tag size="small" :type="backtestQualified(run) ? 'success' : 'default'" :bordered="false">{{ backtestQualified(run) ? '满足审阅门槛' : '仅试跑/未达门槛' }}</n-tag></div></div><n-empty v-else size="small" description="暂无回测记录；运行任务后会在此保留可审阅的摘要。" /></div>
            <div class="optimization-review"><div class="version-heading"><div><b>历史参数寻优</b><small>按信号交易日顺序 70% 训练、30% 样本外验证；训练≥300笔/80日、验证≥120笔/30日，并要求双区间胜率与平均收益均通过。只收紧已完成基线中的选股条件，不改版本。</small></div><n-button size="tiny" secondary :loading="loadingOptimizations" @click="loadOptimizations">刷新记录</n-button></div><template v-if="optimizationReviews.length"><div v-for="review in optimizationReviews" :key="review.run.run_code" class="optimization-run"><div class="optimization-run-head"><span><b>{{ review.run.run_code }}</b><small>训练截止 {{ review.run.train_end_date }} · {{ optimizationRunStatusLabel(review.run.status) }}</small></span><span><b>{{ optimizationNumber(review.run.summary, 'baseline_trade_count') }} 笔基线 / {{ optimizationNumber(review.run.summary, 'trial_count') }} 组</b><small>通过 {{ optimizationNumber(review.run.summary, 'eligible_trial_count') }} 组</small></span></div><div v-if="review.trials.length" class="optimization-trial-list"><div v-for="trial in review.trials.slice(0, 5)" :key="trial.trial_no" class="optimization-trial"><span><b>#{{ trial.rank_no || '-' }}</b><small>{{ optimizationPatchLabel(trial.parameter_patch) }}</small></span><span><b>训练 {{ optimizationNumber(trial.train_summary, 'completed_trade_count') }} 笔</b><small>胜率 {{ optimizationPercent(trial.train_summary, 'win_rate_pct') }} · 均值 {{ optimizationPercent(trial.train_summary, 'average_net_return_pct') }}</small></span><span><b>验证 {{ optimizationNumber(trial.validation_summary, 'completed_trade_count') }} 笔</b><small>胜率 {{ optimizationPercent(trial.validation_summary, 'win_rate_pct') }} · 均值 {{ optimizationPercent(trial.validation_summary, 'average_net_return_pct') }}</small></span><n-tag size="small" :type="optimizationVerdictType(trial.verdict)" :bordered="false">{{ optimizationVerdictLabel(trial.verdict) }}</n-tag></div></div><small v-else>该寻优没有产生可比较试验。</small></div></template><n-empty v-else size="small" description="先完成一个未触及候选上限的完整基线回测，再运行历史参数寻优。" /></div>
            <div class="editor-actions"><n-button :loading="saving" @click="save">保存研究配置</n-button></div>
          </template>
          <n-empty v-else description="选择左侧策略后查看研究配置" />
        </section>
      </section>

      <section class="surface candidates-surface">
        <div class="panel-heading"><div><span class="panel-kicker">候选与执行链路</span><h2>策略候选</h2></div><span class="muted">22:25 任务只扫描已完成盘后事实；T+1 未出现买点不会生成模拟成交。</span></div>
        <div class="candidate-filters"><n-select v-model:value="candidateStrategyCode" clearable :options="strategyOptions" placeholder="全部策略" /><n-input v-model:value="candidateTradeDate" clearable placeholder="报告日 YYYY-MM-DD" @keyup.enter="loadCandidates" /><n-button secondary :loading="loadingCandidates" @click="loadCandidates">查询</n-button></div>
        <div v-if="candidates.length" class="candidate-table"><div class="candidate-row candidate-head"><span>候选日 / 策略</span><span>股票</span><span>评分</span><span>确认状态</span><span>模拟交易</span></div><div v-for="item in candidates" :key="item.id" class="candidate-row"><span><b>{{ item.signal_trade_date }}</b><small>{{ item.strategy_name }}</small></span><span><b>{{ item.stock_name || item.stock_code }}</b><small>{{ item.stock_code }}</small></span><span>{{ formatNumber(item.score) }}<small>{{ item.rank_no ? `第 ${item.rank_no} 名` : '-' }}</small></span><span><n-tag size="small" :type="candidateStatusType(item.candidate_status)" :bordered="false">{{ candidateStatusLabel(item.candidate_status) }}</n-tag><small>{{ item.confirmation_deadline || '确认日期待 evaluator 写入' }}</small></span><span><template v-if="item.paper_trade"><b>{{ paperTradeLabel(item.paper_trade.trade_status) }}</b><small>{{ item.paper_trade.realized_pnl_pct == null ? `买入 ${item.paper_trade.entry_price}` : `收益 ${formatPercent(item.paper_trade.realized_pnl_pct)}` }}</small></template><small v-else>未成交</small></span></div></div>
        <n-empty v-else description="暂无策略候选。只有 paper 版本会由盘后候选任务扫描；研究草稿不会误发信号。" />
      </section>
    </n-spin>

    <n-modal v-model:show="createOpen" preset="card" title="新建短线策略研究草稿" style="width: min(620px, calc(100vw - 28px))">
      <n-form label-placement="top"><n-form-item label="实现模板"><n-select v-model:value="createForm.implementation_code" :options="templateOptions" placeholder="选择已实现且有测试的策略模板" @update:value="applyTemplate" /></n-form-item><n-form-item label="策略代码"><n-input v-model:value="createForm.strategy_code" placeholder="例如 my_theme_first_board" /></n-form-item><n-form-item label="策略名称"><n-input v-model:value="createForm.strategy_name" placeholder="例如 我的首板主线接力" /></n-form-item><n-form-item label="候选确认时点（由实现模板锁定）"><n-input :value="entryModeLabel(createForm.entry_mode)" disabled /></n-form-item><n-form-item label="默认最长持有（由实现模板锁定）"><n-input :value="`${createForm.max_holding_trade_days} 个交易日`" disabled /></n-form-item><n-form-item label="研究说明"><n-input v-model:value="createForm.description" type="textarea" :autosize="{ minRows: 3, maxRows: 6 }" /></n-form-item></n-form>
      <template #footer><div class="modal-actions"><n-button @click="createOpen = false">取消</n-button><n-button type="primary" :loading="creating" @click="create">创建草稿</n-button></div></template>
    </n-modal>

    <n-modal v-model:show="createVersionOpen" preset="card" title="新建不可变策略参数版本" style="width: min(720px, calc(100vw - 28px))">
      <n-alert type="warning" :show-icon="true" style="margin-bottom:12px">选股实现与确认时点固定；此处只调整公共市场门槛、候选上限和模拟风控。新版本必须重新回测，旧版本及历史候选不会被改写。</n-alert>
      <n-form label-placement="top"><div class="version-form-grid"><n-form-item label="实现模板"><n-input :value="versionForm.implementation_code" disabled /></n-form-item><n-form-item label="最低成交额（元）"><n-input-number v-model:value="versionForm.minimum_amount_yuan" :min="0" :step="10000000" /></n-form-item><n-form-item label="最低风险偏好分"><n-input-number v-model:value="versionForm.minimum_market_score" :min="0" :max="100" /></n-form-item><n-form-item label="每日最多候选"><n-input-number v-model:value="versionForm.max_candidates" :min="1" :max="200" /></n-form-item><n-form-item label="初始模拟数量（100 股整数倍）"><n-input-number v-model:value="versionForm.initial_quantity" :min="100" :step="100" /></n-form-item><n-form-item label="硬止损（%）"><n-input-number v-model:value="versionForm.hard_stop_loss_pct" :min="-30" :max="-0.1" :step="0.5" /></n-form-item><n-form-item label="第一止盈（%）"><n-input-number v-model:value="versionForm.take_profit_first_pct" :min="0.1" :max="100" :step="0.5" /></n-form-item><n-form-item label="第二止盈（%）"><n-input-number v-model:value="versionForm.take_profit_second_pct" :min="0.1" :max="100" :step="0.5" /></n-form-item><n-form-item label="最长持有（交易日）"><n-input-number v-model:value="versionForm.max_holding_trade_days" :min="1" :max="20" /></n-form-item></div></n-form>
      <template #footer><div class="modal-actions"><n-button @click="createVersionOpen = false">取消</n-button><n-button type="primary" :loading="creatingVersion" @click="createVersion">创建版本并进入回测</n-button></div></template>
    </n-modal>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { NAlert, NButton, NEmpty, NForm, NFormItem, NInput, NInputNumber, NModal, NSelect, NSpin, NTag, useMessage } from 'naive-ui';
import { Plus, RefreshCw } from 'lucide-vue-next';
import { strategyCenterApi } from '@/api/strategy-center';
import { schedulerApi } from '@/api/scheduler';
import type { StrategyBacktestRun, StrategyCandidate, StrategyDashboard, StrategyDefinition, StrategyEntryMode, StrategyOptimizationReview, StrategyStatus, StrategyTemplate, StrategyVersion } from '@/types/strategy-center';

const message = useMessage();
const dashboard = ref<StrategyDashboard | null>(null);
const selected = ref<StrategyDefinition | null>(null);
const candidates = ref<StrategyCandidate[]>([]);
const templates = ref<StrategyTemplate[]>([]); const selectedVersions = ref<StrategyVersion[]>([]); const backtestRuns = ref<StrategyBacktestRun[]>([]); const optimizationReviews = ref<StrategyOptimizationReview[]>([]);
const loading = ref(false); const loadingCandidates = ref(false); const creating = ref(false); const saving = ref(false); const createOpen = ref(false); const createVersionOpen = ref(false); const bootstrapping = ref(false); const loadingVersions = ref(false); const loadingBacktests = ref(false); const loadingOptimizations = ref(false); const creatingVersion = ref(false); const runningVersion = ref<number | null>(null); const optimizingVersion = ref<number | null>(null); const promotingVersion = ref<number | null>(null);
const candidateStrategyCode = ref<string | null>(null); const candidateTradeDate = ref('');
const backtestStartDate = ref(''); const backtestEndDate = ref(''); const researchCandidateLimit = ref(1000);
const statusOptions = [{ label: '草稿', value: 'draft' }, { label: '研究中', value: 'research' }, { label: '归档', value: 'archived' }];
const createForm = reactive({ strategy_code: '', strategy_name: '', implementation_code: null as string | null, description: '', entry_mode: 'auction' as StrategyEntryMode, max_holding_trade_days: 3 });
const editForm = reactive({ strategy_name: '', description: '', status: 'draft' as StrategyStatus });
const versionForm = reactive({ implementation_code: '', minimum_amount_yuan: 80_000_000, minimum_market_score: 35, max_candidates: 30, initial_quantity: 1000, hard_stop_loss_pct: -4, take_profit_first_pct: 5, take_profit_second_pct: 8, max_holding_trade_days: 3 });
const strategyOptions = computed(() => (dashboard.value?.definitions || []).map((item) => ({ label: `${item.strategy_name} (${item.strategy_code})`, value: item.strategy_code })));
const templateOptions = computed(() => templates.value.map((item) => ({ label: `${item.strategy_name}（${entryModeLabel(item.entry_mode)}）`, value: item.strategy_code })));

function candidateCount(status: string) { return dashboard.value?.candidate_counts?.[status] || 0; }
function tradeCount(status: string) { return dashboard.value?.paper_trade_counts?.[status] || 0; }
function entryModeLabel(value: string) { return ({ auction: '集合竞价确认', open: '开盘确认', intraday: '盘中确认' } as Record<string, string>)[value] || value; }
function statusLabel(value: string) { return ({ draft: '草稿', research: '研究中', paper: '模拟运行', archived: '已归档' } as Record<string, string>)[value] || value; }
function statusType(value: string) { return ({ draft: 'default', research: 'warning', paper: 'success', archived: 'default' } as Record<string, 'default' | 'warning' | 'success'>)[value] || 'default'; }
function versionStatusLabel(value: string) { return ({ draft: '草稿', backtest_ready: '回测待审', paper: '模拟运行', retired: '已退役' } as Record<string, string>)[value] || value; }
function versionStatusType(value: string) { return ({ draft: 'default', backtest_ready: 'warning', paper: 'success', retired: 'default' } as Record<string, 'default' | 'warning' | 'success'>)[value] || 'default'; }
function candidateStatusLabel(value: string) { return ({ pending_confirmation: '待次日确认', watching: '监控中', entry_triggered: '已触发买点', not_triggered: '未触发买点', expired: '已过期', cancelled: '已取消' } as Record<string, string>)[value] || value; }
function candidateStatusType(value: string) { return ({ pending_confirmation: 'warning', watching: 'info', entry_triggered: 'success', not_triggered: 'default', expired: 'default', cancelled: 'error' } as Record<string, 'default' | 'warning' | 'info' | 'success' | 'error'>)[value] || 'default'; }
function paperTradeLabel(value: string) { return ({ open: '模拟持有', closed: '已结束', void: '已作废' } as Record<string, string>)[value] || value; }
function formatNumber(value: number | null) { return typeof value === 'number' ? value.toFixed(1) : '-'; }
function formatPercent(value: number | null) { return typeof value === 'number' ? `${value >= 0 ? '+' : ''}${value.toFixed(2)}%` : '-'; }
function versionMetric(version: StrategyVersion) { const result = version.validation_summary?.latest_completed_backtest as Record<string, unknown> | undefined; const trades = Number(result?.completed_trade_count || 0); const signalDays = Number(result?.signal_trade_date_count || 0); const winRate = result?.win_rate_pct; return trades ? `${trades} 笔 / ${signalDays}/120 日 / 胜率 ${typeof winRate === 'number' ? `${winRate.toFixed(1)}%` : '-'}` : '未完成基线回测'; }
function backtestRunStatusLabel(value: string) { return ({ running: '运行中', completed: '已完成', failed: '失败' } as Record<string, string>)[value] || value; }
function backtestSummaryNumber(run: StrategyBacktestRun, key: string) { return Number(run.summary?.[key] || 0).toLocaleString(); }
function backtestSummaryPercent(run: StrategyBacktestRun, key: string) { const value = run.summary?.[key]; return typeof value === 'number' ? `${value >= 0 ? '+' : ''}${value.toFixed(2)}%` : '-'; }
function backtestQualified(run: StrategyBacktestRun) { return run.summary?.qualified_for_paper_review === true; }
function backtestReturnClass(run: StrategyBacktestRun) { const value = run.summary?.average_net_return_pct; return typeof value === 'number' && value < 0 ? 'negative-return' : 'positive-return'; }
function optimizationNumber(summary: Record<string, unknown>, key: string) { return Number(summary?.[key] || 0).toLocaleString(); }
function optimizationPercent(summary: Record<string, unknown>, key: string) { const value = summary?.[key]; return typeof value === 'number' ? `${value >= 0 ? '+' : ''}${value.toFixed(2)}%` : '-'; }
function optimizationRunStatusLabel(value: string) { return ({ running: '运行中', completed: '已完成', failed: '失败' } as Record<string, string>)[value] || value; }
function optimizationVerdictLabel(value: string) { return ({ eligible: '可复验候选', rejected: '不通过', data_insufficient: '样本不足' } as Record<string, string>)[value] || value; }
function optimizationVerdictType(value: string) { return ({ eligible: 'success', rejected: 'error', data_insufficient: 'warning' } as Record<string, 'success' | 'error' | 'warning'>)[value] || 'default'; }
function optimizationPatchLabel(patch: Record<string, unknown>) { const signal = patch.signal as Record<string, number> | undefined; const marketGate = patch.market_gate as Record<string, number> | undefined; return [...Object.entries(signal || {}).map(([key, value]) => `${key}=${value}`), ...Object.entries(marketGate || {}).map(([key, value]) => `${key}=${value}`)].join('，') || '基线参数'; }
function select(item: StrategyDefinition) { selected.value = item; editForm.strategy_name = item.strategy_name; editForm.description = item.description || ''; editForm.status = item.status; candidateStrategyCode.value = item.strategy_code; void loadCandidates(); void loadVersions(); void loadBacktests(); void loadOptimizations(); }
async function loadTemplates() { try { templates.value = await strategyCenterApi.templates(); } catch (error) { message.error(error instanceof Error ? error.message : '读取策略模板失败'); } }
async function load() { loading.value = true; try { dashboard.value = await strategyCenterApi.dashboard(); const refreshed = selected.value && dashboard.value.definitions.find((item) => item.strategy_code === selected.value?.strategy_code); if (refreshed) select(refreshed); else if (!selected.value && dashboard.value.definitions[0]) select(dashboard.value.definitions[0]); } catch (error) { message.error(error instanceof Error ? error.message : '读取策略中心失败'); } finally { loading.value = false; } }
async function loadCandidates() { loadingCandidates.value = true; try { candidates.value = await strategyCenterApi.candidates({ strategy_code: candidateStrategyCode.value || undefined, signal_trade_date: candidateTradeDate.value.trim() || undefined, limit: 200 }); } catch (error) { message.error(error instanceof Error ? error.message : '读取策略候选失败'); } finally { loadingCandidates.value = false; } }
async function loadVersions() { if (!selected.value) return; loadingVersions.value = true; try { selectedVersions.value = await strategyCenterApi.versions(selected.value.strategy_code); } catch (error) { message.error(error instanceof Error ? error.message : '读取策略版本失败'); } finally { loadingVersions.value = false; } }
async function loadBacktests() { if (!selected.value) return; loadingBacktests.value = true; try { backtestRuns.value = await strategyCenterApi.backtests(selected.value.strategy_code); } catch (error) { message.error(error instanceof Error ? error.message : '读取回测记录失败'); } finally { loadingBacktests.value = false; } }
async function loadOptimizations() { if (!selected.value) return; loadingOptimizations.value = true; try { optimizationReviews.value = await strategyCenterApi.optimizations(selected.value.strategy_code); } catch (error) { message.error(error instanceof Error ? error.message : '读取参数寻优记录失败'); } finally { loadingOptimizations.value = false; } }
function openCreate() { createForm.strategy_code = ''; createForm.strategy_name = ''; createForm.implementation_code = null; createForm.description = ''; createForm.entry_mode = 'auction'; createForm.max_holding_trade_days = 3; createOpen.value = true; }
function applyTemplate(code: string) { const template = templates.value.find((item) => item.strategy_code === code); if (!template) return; createForm.entry_mode = template.entry_mode; createForm.max_holding_trade_days = template.max_holding_trade_days; if (!createForm.strategy_name) createForm.strategy_name = template.strategy_name; if (!createForm.description) createForm.description = template.description; }
async function create() { if (!createForm.strategy_code || !createForm.strategy_name || !createForm.implementation_code) { message.warning('请选择实现模板并填写策略代码、名称'); return; } creating.value = true; try { const created = await strategyCenterApi.create({ ...createForm, description: createForm.description || null }); createOpen.value = false; await load(); const item = dashboard.value?.definitions.find((row) => row.strategy_code === created.strategy_code); if (item) select(item); message.success('策略草稿、初始版本和专属动态股票池已创建'); } catch (error) { message.error(error instanceof Error ? error.message : '创建策略草稿失败'); } finally { creating.value = false; } }
async function save() { if (!selected.value) return; saving.value = true; try { await strategyCenterApi.update(selected.value.strategy_code, { ...editForm, description: editForm.description || null }); await load(); message.success('研究配置已保存'); } catch (error) { message.error(error instanceof Error ? error.message : '保存策略失败'); } finally { saving.value = false; } }
async function bootstrapBuiltins() { bootstrapping.value = true; try { const result = await strategyCenterApi.bootstrapBuiltins(); await load(); message.success(result.created.length ? `已创建 ${result.created.length} 个内置策略草稿` : '内置策略已初始化'); } catch (error) { message.error(error instanceof Error ? error.message : '初始化内置策略失败'); } finally { bootstrapping.value = false; } }
function nestedNumber(source: Record<string, unknown> | undefined, path: string[], fallback: number) { let value: unknown = source; for (const key of path) value = value && typeof value === 'object' ? (value as Record<string, unknown>)[key] : undefined; return typeof value === 'number' && Number.isFinite(value) ? value : fallback; }
function openCreateVersion() { const base = selectedVersions.value[0]; if (!base || !selected.value) { message.warning('请先刷新并选择一个已有版本'); return; } const rule = base.rule_config; const risk = base.risk_config; versionForm.implementation_code = base.implementation_code; versionForm.minimum_amount_yuan = nestedNumber(rule, ['universe', 'minimum_amount_yuan'], 80_000_000); versionForm.minimum_market_score = nestedNumber(rule, ['market_gate', 'minimum_market_risk_on_score'], 35); versionForm.max_candidates = nestedNumber(rule, ['selection', 'max_candidates'], 30); versionForm.initial_quantity = nestedNumber(risk, ['initial_quantity'], 1000); versionForm.hard_stop_loss_pct = nestedNumber(risk, ['hard_stop_loss_pct'], -4); versionForm.take_profit_first_pct = nestedNumber(risk, ['take_profit_legs', '0', 'trigger_return_pct'], 5); versionForm.take_profit_second_pct = nestedNumber(risk, ['take_profit_legs', '1', 'trigger_return_pct'], 8); versionForm.max_holding_trade_days = nestedNumber(risk, ['time_exit', 'trade_days'], selected.value.max_holding_trade_days); createVersionOpen.value = true; }
async function createVersion() { if (!selected.value || versionForm.take_profit_second_pct <= versionForm.take_profit_first_pct) { message.warning('第二止盈必须高于第一止盈'); return; } creatingVersion.value = true; try { await strategyCenterApi.createVersion(selected.value.strategy_code, { implementation_code: versionForm.implementation_code, rule_config: { universe: { minimum_amount_yuan: versionForm.minimum_amount_yuan }, market_gate: { minimum_market_risk_on_score: versionForm.minimum_market_score }, selection: { max_candidates: versionForm.max_candidates } }, risk_config: { initial_quantity: versionForm.initial_quantity, hard_stop_loss_pct: versionForm.hard_stop_loss_pct, take_profit_legs: [{ trigger_return_pct: versionForm.take_profit_first_pct, sell_ratio: 0.5 }, { trigger_return_pct: versionForm.take_profit_second_pct, sell_ratio: 1 }], max_holding_trade_days: versionForm.max_holding_trade_days, time_exit: { enabled: true, trade_days: versionForm.max_holding_trade_days } } }); createVersionOpen.value = false; await loadVersions(); message.success('已创建新版本；请先运行基线回测并审阅结果。'); } catch (error) { message.error(error instanceof Error ? error.message : '创建策略版本失败'); } finally { creatingVersion.value = false; } }
async function runBacktest(versionNo: number, baselineCandidateLimit?: number) { if (!selected.value || !backtestStartDate.value || !backtestEndDate.value) { message.warning('请先填写回测开始和结束日期'); return; } runningVersion.value = versionNo; try { const run = await schedulerApi.runJob('run_strategy_backtest', { strategy_code: selected.value.strategy_code, version_no: versionNo, start_date: backtestStartDate.value, end_date: backtestEndDate.value, fee_rate: 0.0005, slippage_bps: 10, ...(baselineCandidateLimit ? { baseline_candidate_limit: baselineCandidateLimit } : {}) }, true); message.success(`已提交回测任务 ${run.run_id.slice(0, 8)}，可在调度中心查看进度`); } catch (error) { message.error(error instanceof Error ? error.message : '提交回测任务失败'); } finally { runningVersion.value = null; } }
function runResearchBaseline(versionNo: number) { runBacktest(versionNo, researchCandidateLimit.value); }
async function runOptimization(versionNo: number) { if (!selected.value) return; optimizingVersion.value = versionNo; try { const run = await schedulerApi.runJob('optimize_strategy_parameters', { strategy_code: selected.value.strategy_code, version_no: versionNo, train_ratio: 0.7, max_trials: 500 }, true); message.success(`已提交历史参数寻优 ${run.run_id.slice(0, 8)}；完成后在此查看训练/验证结果。`); } catch (error) { message.error(error instanceof Error ? error.message : '提交历史参数寻优失败'); } finally { optimizingVersion.value = null; } }
async function promoteVersion(versionNo: number) { if (!selected.value) return; promotingVersion.value = versionNo; try { await strategyCenterApi.promoteVersion(selected.value.strategy_code, versionNo); await load(); await loadVersions(); message.success('版本已进入 paper 模拟运行；实时底座将从策略池接入候选。'); } catch (error) { message.error(error instanceof Error ? error.message : '提升 paper 版本失败'); } finally { promotingVersion.value = null; } }
onMounted(() => { void loadTemplates(); void load(); void loadCandidates(); });
</script>

